/// <summary>
/// CB521_ExciseRegister
/// Contract class to update excise information table
/// </summary>
[DataContractAttribute]
class METExciseInformationTableUpdateContract
{
    METTransactionType  metTransactionType;
    InventTransType     referenceId;

}

Method.Source:
    /// <summary>
    /// Parameter method for invent trans type
    /// </summary>
    /// <param name = "_referenceId">Invent trans type reference</param>
    /// <returns>InventTransType</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public InventTransType  parmReferenceId(InventTransType     _referenceId = referenceId)
    {
        referenceId = _referenceId;

        return referenceId;
    }

    /// <summary>
    /// Parameter method for transaction type
    /// </summary>
    /// <param name = "_metTransactionType">Transaction type for reference</param>
    /// <returns>METTransactionType</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public METTransactionType  parmTransactionType(METTransactionType     _metTransactionType = metTransactionType)
    {
        metTransactionType = _metTransactionType;

        return metTransactionType;
    }
